"""Demo 1: Capacity, the doubling law, and dense metabolic cost."""
from __future__ import annotations
import itertools
from typing import List, Tuple

Pattern = Tuple[int, ...]

def all_patterns(n: int) -> List[Pattern]:
    return list(itertools.product((0, 1), repeat=n))

def capacity(n: int) -> int:
    return 2 ** n

def average_dense_energy(n: int) -> float:
    pats = all_patterns(n)
    return sum(sum(p) for p in pats) / len(pats)

def main() -> None:
    print("N  capacity  ratio   avg-active")
    prev = 1
    for n in range(1, 11):
        c = capacity(n)
        print(f"{n:2d}  {c:7d}   {c/prev:.1f}     {average_dense_energy(min(n,12)):.2f}")
        prev = c

if __name__ == "__main__":
    main()

"""Demo 2: Sparse counts C(N,k) and the bits-per-spike efficiency frontier."""
from __future__ import annotations
import math
from typing import List, Tuple

def bits_per_spike(n: int, k: int) -> float:
    return math.log2(math.comb(n, k)) / k if k else 0.0

def efficiency_frontier(n: int) -> List[Tuple[int, int, float]]:
    return [(k, math.comb(n, k), bits_per_spike(n, k)) for k in range(1, n + 1)]

def main() -> None:
    for n in (8, 16, 32):
        print(f"\nN = {n}: one-hot advantage log2(N) = {math.log2(n):.3f} bits/spike")
        for k, c, eta in efficiency_frontier(n)[:6]:
            print(f"  k={k:2d}  C(N,k)={c:8d}  eta={eta:.3f}")

if __name__ == "__main__":
    main()

"""Demo 3: Singleton bound, tightness witnesses, and robust-capacity law."""
from __future__ import annotations
import itertools, math
from typing import List, Sequence, Tuple

Pattern = Tuple[int, ...]

def all_patterns(n: int) -> List[Pattern]:
    return list(itertools.product((0, 1), repeat=n))

def hamming(x: Pattern, y: Pattern) -> int:
    return sum(1 for a, b in zip(x, y) if a != b)

def min_distance(book: Sequence[Pattern]) -> int:
    d = min((hamming(a, b) for a, b in itertools.combinations(book, 2)), default=0)
    return d

def greedy_codebook(n: int, d: int) -> List[Pattern]:
    chosen: List[Pattern] = []
    for p in all_patterns(n):
        if all(hamming(p, q) >= d for q in chosen):
            chosen.append(p)
    return chosen

def singleton_bound(n: int, d: int) -> int:
    return 2 ** (n + 1 - d)

def main() -> None:
    n = 7
    print(f"N = {n}")
    for d in range(1, n + 1):
        book = greedy_codebook(n, d)
        assert len(book) <= singleton_bound(n, d)
        print(f"  d={d}  Singleton={singleton_bound(n,d):3d}  greedy|C|={len(book):3d}")
    print("Tightness: full code at d=1, repetition {0..0,1..1} at d=N.")
    for t in range(n // 2 + 1):
        print(f"  t={t}: robust ceiling 2^(N-2t) = {2 ** (n - 2*t)}")

if __name__ == "__main__":
    main()

