from __future__ import annotations
import itertools
from typing import List, Sequence, Tuple

Pattern = Tuple[int, ...]

def hamming(x: Pattern, y: Pattern) -> int:
    """Hamming distance between two neural activity patterns."""
    return sum(1 for a, b in zip(x, y) if a != b)

def greedy_min_distance_code(n: int, d: int) -> List[Pattern]:
    """Greedily construct a codebook on n neurons with minimum distance >= d.

    Scans all 2^n patterns in lexicographic order and admits a pattern iff it is
    at Hamming distance >= d from every previously admitted codeword. The result
    is guaranteed by the Singleton bound to satisfy |C| <= 2^(n+1-d).
    """
    chosen: List[Pattern] = []
    for p in itertools.product((0, 1), repeat=n):
        if all(hamming(p, q) >= d for q in chosen):
            chosen.append(p)
    return chosen

def singleton_ceiling(n: int, d: int) -> int:
    """The Singleton capacity ceiling 2^(n+1-d)."""
    return 2 ** (n + 1 - d)

